--- README.md
     1	# inkwell-ssg
     2	
     3	A small static blog generator. Run node src/build.js in a site folder.
     4	
     5	Run the tests with npm test.
--- docs/CONTRIBUTING.md
     1	# Contributing
     2	
     3	inkwell-ssg is vendored: a site copies this whole folder into its own repository and runs it with
     4	plain node. So it has no runtime dependencies at all. Use Node built-ins only, and keep the
     5	dependencies block in package.json empty.
--- package.json
     1	{
     2	  "name": "inkwell-ssg",
     3	  "version": "1.12.0",
     4	  "private": true,
     5	  "scripts": {
     6	    "test": "node --test"
     7	  },
     8	  "dependencies": {}
     9	}
--- site.json
     1	{
     2	  "title": "Field Notes",
     3	  "baseUrl": "https://example.test/blog",
     4	  "author": "Rui Tanaka"
     5	}
--- src/build.js
     1	const { isPublished } = require('./posts');
     2	const { permalink } = require('./permalink');
     3	const { escapeHtml } = require('./html');
     4	const { sitemap } = require('./sitemap');
     5	
     6	function build(site, posts, now = Date.now()) {
     7	  const out = {};
     8	  for (const p of posts.filter((x) => isPublished(x, now))) {
     9	    out[permalink(p) + 'index.html'] = '<h1>' + escapeHtml(p.title) + '</h1>\n' + p.body;
    10	  }
    11	  out['/sitemap.xml'] = sitemap(site, posts, now);
    12	  return out;
    13	}
    14	
    15	module.exports = { build };
--- src/devserver.js
     1	const http = require('node:http');
     2	
     3	function serve(files, port = 4000) {
     4	  return http.createServer((req, res) => {
     5	    const body = files[req.url] ?? files[req.url + 'index.html'];
     6	    if (!body) { res.writeHead(404); res.end(); return; }
     7	    res.writeHead(200);
     8	    res.end(body + '<script>new EventSource("/__reload").onmessage = () => location.reload()</script>');
     9	  }).listen(port);
    10	}
    11	
    12	module.exports = { serve };
--- src/highlight.js
     1	const KEYWORDS = ['const', 'let', 'function', 'return', 'if', 'else'];
     2	
     3	function highlight(code) {
     4	  return code.replace(/\b(\w+)\b/g, (w) => (KEYWORDS.includes(w) ? '<b>' + w + '</b>' : w));
     5	}
     6	
     7	module.exports = { highlight };
--- src/html.js
     1	function escapeHtml(s) {
     2	  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
     3	}
     4	
     5	module.exports = { escapeHtml };
--- src/minify.js
     1	function minify(html) {
     2	  return html.replace(/>\s+</g, '><').trim();
     3	}
     4	
     5	module.exports = { minify };
--- src/permalink.js
     1	function permalink(post) {
     2	  const [y, m] = post.publish_at.split('-');
     3	  return '/' + y + '/' + m + '/' + post.slug + '/';
     4	}
     5	
     6	function absoluteUrl(site, p) {
     7	  return site.baseUrl.replace(/\/$/, '') + p;
     8	}
     9	
    10	module.exports = { permalink, absoluteUrl };
--- src/posts.js
     1	const fs = require('node:fs');
     2	const path = require('node:path');
     3	
     4	function parse(text, file) {
     5	  const m = /^---\n([\s\S]*?)\n---\n([\s\S]*)$/.exec(text);
     6	  const meta = {};
     7	  for (const line of (m ? m[1] : '').split('\n')) {
     8	    const i = line.indexOf(':');
     9	    if (i > 0) meta[line.slice(0, i).trim()] = line.slice(i + 1).trim();
    10	  }
    11	  return { file, title: meta.title, slug: meta.slug, publish_at: meta.publish_at, draft: meta.draft === 'true', body: m ? m[2] : text };
    12	}
    13	
    14	function loadPosts(dir) {
    15	  return fs.readdirSync(dir).filter((f) => f.endsWith('.md')).sort().map((f) => parse(fs.readFileSync(path.join(dir, f), 'utf8'), f));
    16	}
    17	
    18	function isPublished(post, now = Date.now()) {
    19	  return !post.draft && Date.parse(post.publish_at) <= now;
    20	}
    21	
    22	module.exports = { loadPosts, isPublished, parse };
--- src/sitemap.js
     1	const { absoluteUrl, permalink } = require('./permalink');
     2	const { isPublished } = require('./posts');
     3	
     4	function sitemap(site, posts, now = Date.now()) {
     5	  const urls = posts.filter((p) => isPublished(p, now)).map((p) => '  <url><loc>' + absoluteUrl(site, permalink(p)) + '</loc></url>');
     6	  return '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' + urls.join('\n') + '\n</urlset>\n';
     7	}
     8	
     9	module.exports = { sitemap };
