     1	// Old links are indexed and shared widely, so these URLs never change. Sites are often served under a
     2	// path (baseUrl https://example.test/blog), so every absolute link goes through absoluteUrl().
     3	const test = require('node:test');
     4	const assert = require('node:assert');
     5	const { permalink, absoluteUrl } = require('../src/permalink');
     6	
     7	const site = { baseUrl: 'https://example.test/blog/' };
     8	
     9	test('permalinks are /YYYY/MM/slug/', () => {
    10	  assert.strictEqual(permalink({ slug: 'hello-world', publish_at: '2026-10-01T09:00:00Z' }), '/2026/10/hello-world/');
    11	});
    12	
    13	test('absolute URLs keep the base path', () => {
    14	  assert.strictEqual(absoluteUrl(site, '/2026/10/hello-world/'), 'https://example.test/blog/2026/10/hello-world/');
    15	});
